#!/bin/zsh
# Keep the generated Xcode project in step with the checkout, then open it.
#
# The .xcodeproj is generated by XcodeGen from project.yml and never committed, so a pull that
# adds a file to iOS/ or ShareExtension/, or changes project.yml, needs a regeneration before
# Xcode sees it. This script regenerates only when something XcodeGen reads has changed (a
# fingerprint kept inside the project), so it is cheap to run every time and safe to call from
# git hooks (see scripts/install-hooks.sh). Files inside the Swift packages never need it: Xcode
# reads Packages/* through SwiftPM directly.
#
# Usage: scripts/xcode.sh [--pull] [--no-open] [--force] [--quiet]
#   --pull     git pull --ff-only first
#   --no-open  regenerate if needed, but don't open Xcode (what the hooks use)
#   --force    regenerate even if nothing changed
#   --quiet    print only when something happens
set -euo pipefail

# GUI git clients run hooks with a minimal PATH; Homebrew's bin is where xcodegen lives.
path=(/opt/homebrew/bin /usr/local/bin $path)

ios=${0:A:h:h}
repo=${ios:h}
project=$ios/Enchiridion.xcodeproj
stamp=$project/.enchiridion-stamp

pull=0 open=1 force=0 quiet=0
for arg in "$@"; do
  case $arg in
    --pull) pull=1 ;;
    --no-open) open=0 ;;
    --force) force=1 ;;
    --quiet) quiet=1 ;;
    -h|--help) sed -n '2,17p' $0 | sed 's/^# \{0,1\}//'; exit 0 ;;
    *) print -u2 "xcode.sh: unknown option $arg (try --help)"; exit 2 ;;
  esac
done

say() { (( quiet )) || print -- "$@" }

if (( pull )); then
  say "▸ git pull --ff-only"
  git -C $repo pull --ff-only
fi

if ! command -v xcodegen >/dev/null; then
  print -u2 "xcode.sh: xcodegen isn't installed. Install it with: brew install xcodegen"
  exit 1
fi

# Everything the generated project depends on: the spec, the xcconfigs it names, the list of
# files in the target folders (the project lists each one), and the XcodeGen version.
fingerprint() {
  {
    cat $ios/project.yml $ios/Config/*.xcconfig(N)
    (cd $ios && find iOS ShareExtension -type f ! -name '.DS_Store' ! -name 'Info.plist' | LC_ALL=C sort)
    xcodegen --version
  } | shasum -a 256 | cut -d' ' -f1
}

current=$(fingerprint)
if (( force )) || [[ ! -d $project || ! -f $stamp || $(<$stamp) != $current ]]; then
  say "▸ xcodegen generate"
  (cd $ios && xcodegen generate --quiet)
  print -n -- $current > $stamp
  (( quiet )) && print "Enchiridion.xcodeproj regenerated (ios/scripts/xcode.sh)"
else
  say "▸ Enchiridion.xcodeproj is up to date"
fi

if (( open )); then
  open $project
fi
